parameters.jsCode:
const bill = $('Information Extractor').first().json.output.bill;
const rates = {};
for (const i of $input.all()) rates[i.json.item] = Number(i.json.rate_pkr);

const units = bill / 50;
const kw = Math.ceil((units / 120) * 2) / 2; // 0.5 kW steps

const panels = kw * 1000 * rates.panel;
const inverter = kw * rates.inverter;
const structure = kw * rates.structure;
const installation = kw * rates.installation;
const net = rates.net_metering;
const total = panels + inverter + structure + installation + net;
const score = bill >= 40000 ? 'hot' : bill >= 20000 ? 'warm' : 'cold';

return [{ json: { bill, kw, panels, inverter, structure, installation, net_metering: net, total, score } }];

